public Response update(@RequestHeader("Idempotency-Key") String key, @RequestBody Event e) {
  if (idempotency.exists(key)) return idempotency.getResult(key);
  // begin tx
  updateUser(e);
  kafkaProducer.send(...);
  idempotency.save(key, newResult);
  return ok;
}
